def apply_html(t, lang):
    for a,b in sorted(R[lang].items(),key=lambda x:len(x[0]),reverse=True): t=t.replace(a,b)
    return t

def apply_js(t, lang):
    pairs=[]
    for src,vals in JS_EXTRA.items():
        if lang in vals: pairs.append((src,vals[lang]))
    pairs+=GEN.get(lang,[])
    for a,b in sorted(pairs,key=lambda x:len(x[0]),reverse=True): t=t.replace(a,b)
    return t

def path_url(lang,page):
    if lang=='ko': return BASE+('' if page=='index.html' else page)
    return BASE+lang+'/'+('' if page=='index.html' else page)

def switch_html(current,page):
    opts=''.join(f'<option value="{l}"'+(' selected' if l==current else '')+f'>{html.escape(LABELS[l])}</option>' for l in LANGS)
    return f'<select aria-label="Language" onchange="const p=&quot;{page}&quot;;const l=this.value;const b=&#x27;/pc-checkup/&#x27;;location.href=b+(l===&#x27;ko&#x27;?(p===&#x27;index.html&#x27;?&#x27;&#x27;:p):(l+&#x27;/&#x27;+(p===&#x27;index.html&#x27;?&#x27;&#x27;:p)));">{opts}</select>'

def hreflangs(page):
    parts=[f'<link rel="alternate" hreflang="{l}" href="{path_url(l,page)}">' for l in LANGS]
    parts.append(f'<link rel="alternate" hreflang="x-default" href="{path_url("en",page)}">')
    return ''.join(parts)

for lang in ['de','fr','pt','it','nl','id','vi']:
    target=ROOT/lang
    if target.exists(): shutil.rmtree(target)
    shutil.copytree(ROOT/'en',target)
    for p in target.glob('*'):
        if p.suffix in {'.html','.js'}:
            txt=p.read_text(encoding='utf-8')
            txt=apply_html(txt,lang) if p.suffix=='.html' else apply_js(txt,lang)
            if p.suffix=='.html':
                txt=txt.replace('<html lang="en">',f'<html lang="{lang}">').replace('og:locale" content="en_US"',f'og:locale" content="{OG[lang]}"').replace('"inLanguage":"en"',f'"inLanguage":"{lang}"').replace(BASE+'en/',BASE+lang+'/')
            p.write_text(txt,encoding='utf-8')
for lang in LANGS:
    folder=ROOT if lang=='ko' else ROOT/lang
    for page in PAGES:
        p=folder/page; txt=p.read_text(encoding='utf-8')
        txt=re.sub(r'(?:<link rel="alternate" hreflang="[^"]+" href="[^"]+">)+',hreflangs(page),txt,count=1)
        txt=re.sub(r'<select aria-label="Language".*?</select>',switch_html(lang,page),txt,count=1)
        p.write_text(txt,encoding='utf-8')
urls=[path_url(lang,page) for lang in LANGS for page in PAGES]
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{u}</loc></url>\n' for u in urls)+'</urlset>\n',encoding='utf-8')
print(f'Batch2 locales built: {len(LANGS)} languages, {len(urls)} URLs')
